use super::*;

/// `from_pillar -> to_pillar` counts, the one-line summary of [`meter`].
pub fn by_direction(refs: &[CrossRef]) -> BTreeMap<String, usize> {
    let mut m = BTreeMap::new();
    for r in refs {
        *m.entry(format!("{}->{}", r.from_pillar, r.to_pillar)).or_insert(0) += 1;
    }
    m
}
